insert into codex_blocks (unit_id, ord, block_type, payload, source_ref, reviewed_at, reviewed_by)
values
  ('0c5d9d5702737670', 1, 'lead', '{"text": "Under the arbitrage-free framework, the value of a bond with embedded options is the sum of the arbitrage-free values of its parts. Two equations follow from that, and almost everything else in the module is their consequence."}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('0c5d9d5702737670', 2, 'heading_2', '{"text": "Callable bonds"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('0c5d9d5702737670', 3, 'prose', '{"text": "The decision to exercise a call belongs to the <strong>issuer</strong>. The investor is therefore long the bond but <strong>short the call</strong>, so the option reduces the value of the callable bond relative to the straight bond."}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('0c5d9d5702737670', 4, 'formula', '{"expr": "Value of callable bond = Value of straight bond − Value of issuer call option"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('0c5d9d5702737670', 5, 'formula', '{"expr": "Value of issuer call option = Value of straight bond − Value of callable bond"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('0c5d9d5702737670', 6, 'heading_2', '{"text": "Putable bonds"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('0c5d9d5702737670', 7, 'prose', '{"text": "The decision to exercise a put belongs to the <strong>investor</strong>, who is long both the bond and the option. The option therefore increases the value of the putable bond."}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('0c5d9d5702737670', 8, 'formula', '{"expr": "Value of putable bond = Value of straight bond + Value of investor put option"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('0c5d9d5702737670', 9, 'formula', '{"expr": "Value of investor put option = Value of putable bond − Value of straight bond"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('0c5d9d5702737670', 10, 'key', '{"paras": ["The straight bond is easy — discount its cash flows at the appropriate spot rates. The hard part is valuing the option, because its value is contingent on future interest rates: the issuer''s decision to call depends on the ability to refinance more cheaply. In practice the option value is often backed out as the <em>difference</em> between the straight and the callable bond, rather than valued directly."]}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('0c5d9d5702737670', 11, 'trap', '{"paras": ["Get the signs right and half this module is secure. Callable <strong>subtracts</strong> because the investor is short the option. Putable <strong>adds</strong> because the investor is long it. The party holding the option is the one who benefits from it."]}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('0c5d9d5702737670', 12, 'heading_2', '{"text": "Valuing the default-free, option-free bond"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('0c5d9d5702737670', 13, 'prose', '{"text": "Each cash flow is discounted at the spot rate corresponding to its payment date. Spot rates are not always directly observable but can be inferred from market prices of actively traded on-the-run sovereign bonds. Par rates, spot rates and forward rates are equivalent ways of conveying the same information — knowing any one determines the others."}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('0c5d9d5702737670', 14, 'worked', '{"title": "Equivalent forms of a yield curve", "blocks": [{"text": "Valuing a three-year 4.25% annual coupon bond.", "kind": "prose"}, {"headers": ["Maturity", "Par rate", "Spot rate", "One-year forward"], "rows": [["1", "2.500%", "2.500%", "2.500%  (0 years forward)"], ["2", "3.000%", "3.008%", "3.518%  (1 year forward)"], ["3", "3.500%", "3.524%", "4.564%  (2 years forward)"]], "aligns": ["c", "num", "num", "num"], "kind": "table"}, {"text": "Discounting the 4.25% bond''s cash flows at either the spot rates or the sequence of forward rates gives the same answer — 102.114 for the default-free bond.", "kind": "prose"}]}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored');
insert into codex_blocks (unit_id, ord, block_type, payload, source_ref, reviewed_at, reviewed_by)
values
  ('2a602fb1369c466b', 1, 'lead', '{"text": "One relationship governs this whole section, and it holds for both option types."}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('2a602fb1369c466b', 2, 'key', '{"paras": ["The value of <strong>any</strong> embedded option, regardless of type, <strong>increases</strong> with interest rate volatility. Greater volatility means more opportunities for the option to be exercised."]}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('2a602fb1369c466b', 3, 'prose', '{"text": "Volatility is represented through the dispersion of the interest rate tree. From each node rates may go up or down; the dispersion between those states is determined by the process generating rates from the yield curve and the volatility assumption. Higher volatility, wider dispersion."}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('2a602fb1369c466b', 4, 'heading_2', '{"text": "The consequence differs by option type"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('2a602fb1369c466b', 5, 'table_compare', '{"headers": ["", "Callable bond", "Putable bond"], "rows": [["Option value as σ rises", "Rises", "Rises"], ["Investor''s position in the option", "Short", "Long"], ["Effect on bond value", "<strong>Falls</strong> — value of straight bond less a larger option", "<strong>Rises</strong> — value of straight bond plus a larger option"]]}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('2a602fb1369c466b', 6, 'worked', '{"title": "Volatility and the call option", "blocks": [{"text": "A 30-year 4.50% bond callable at par in 10 years, on a 4% flat yield curve. The value of the straight bond is unaffected by volatility; only the option component moves.", "kind": "prose"}, {"headers": ["Interest rate volatility", "Value of call option"], "rows": [["0%", "4.60% of par"], ["30%", "14.78% of par"]], "aligns": ["c", "num"], "kind": "table"}, {"text": "Note that the straight bond value is the constant in this comparison. All movement in the callable bond comes from the option.", "kind": "prose"}], "answer": "Option value more than triples; callable bond value falls accordingly"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored');
insert into codex_blocks (unit_id, ord, block_type, payload, source_ref, reviewed_at, reviewed_by)
values
  ('b2f2d17792b101cc', 1, 'lead', '{"text": "Level and shape both matter, and they matter in opposite directions for calls and puts."}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('b2f2d17792b101cc', 2, 'heading_2', '{"text": "Level of the curve"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('b2f2d17792b101cc', 3, 'table_compare', '{"headers": ["As interest rates…", "Call option", "Put option"], "rows": [["Fall", "Moves <strong>into</strong> the money — issuer can refinance cheaply", "Moves out of the money"], ["Rise", "Moves out of the money", "Moves <strong>into</strong> the money — investor can reinvest higher"]]}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('b2f2d17792b101cc', 4, 'prose', '{"text": "The call caps the investor''s upside. As rates fall, the straight bond appreciates freely but the callable bond does not, because no investor will pay more than the price at which the bond can be immediately called. The callable bond''s value therefore <strong>rises less rapidly</strong> than the straight bond''s, limiting upside potential."}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('b2f2d17792b101cc', 5, 'key', '{"paras": ["The put is a <strong>hedge against rising rates</strong>. As rates rise the straight bond declines, but the decline is partially offset by the increasing put value. On a move from a 3% flat curve to a 5% flat curve, the straight bond falls 30% while the putable bond''s fall is limited to 22%."]}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('b2f2d17792b101cc', 6, 'heading_2', '{"text": "Shape of the curve"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('b2f2d17792b101cc', 7, 'prose', '{"text": "All else equal, the value of the <strong>call option increases as the yield curve flattens</strong>, and increases further if it inverts."}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('b2f2d17792b101cc', 8, 'table_data', '{"headers": ["Yield curve shape", "Call option value"], "rows": [["Upward sloping, 2% short to 4% long", "≈ 8% of par"], ["Flat at 4%", "≈ 10% of par"], ["Downward sloping, 6% short to 4% long", "&gt; 12% of par"]], "aligns": ["", "num"]}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('b2f2d17792b101cc', 9, 'prose', '{"text": "<em>30-year 4.50% bond callable at par in 10 years, 15% interest rate volatility.</em>"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('b2f2d17792b101cc', 10, 'key', '{"paras": ["The intuition: when the curve is upward sloping, one-period forward rates on the tree are <strong>high</strong>, so opportunities for the issuer to call are <strong>fewer</strong>. When the curve flattens or inverts, many nodes carry lower forward rates, which increases the opportunities to call."]}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('b2f2d17792b101cc', 11, 'heading_3', '{"text": "Moneyness at issue"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('b2f2d17792b101cc', 12, 'list_bullet', '{"items": ["Assuming a normal upward-sloping curve at issue, the call embedded in a callable bond issued at par is <strong>out of the money</strong>. It would not be called if the arbitrage-free forward rates at zero volatility prevailed.", "Callable bonds issued at a <strong>large premium</strong> — common in the US municipal sector — are <strong>in the money</strong>, and will be called if the arbitrage-free forwards prevail."]}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored');
insert into codex_blocks (unit_id, ord, block_type, payload, source_ref, reviewed_at, reviewed_by)
values
  ('715b9a8d5589ad0f', 1, 'lead', '{"text": "The mechanics are backward induction from LM2 with one extra step at every node: check whether the option would be exercised."}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('715b9a8d5589ad0f', 2, 'heading_2', '{"text": "The exercise rule"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('715b9a8d5589ad0f', 3, 'formula', '{"expr": "Callable: value at node = min(computed value, call price)", "label": "Issuer exercises to its benefit"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('715b9a8d5589ad0f', 4, 'formula', '{"expr": "Putable: value at node = max(computed value, put price)", "label": "Investor exercises to their benefit"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('715b9a8d5589ad0f', 5, 'prose', '{"text": "At each node, first compute the value by backward induction exactly as for a straight bond. Then apply the exercise rule. For a callable bond the issuer will call whenever the computed value exceeds the call price, so the node carries the <em>lower</em> of the two. For a putable bond the investor will put whenever the computed value falls below the put price, so the node carries the <em>higher</em>."}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('715b9a8d5589ad0f', 6, 'exam', '{"paras": ["The direction of the min/max is decided by <em>who holds the option</em>, not by which is bigger. The issuer holds the call and acts to reduce what it owes, hence min. The investor holds the put and acts to protect value, hence max."]}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('715b9a8d5589ad0f', 7, 'heading_2', '{"text": "Backward induction with the exercise check"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('715b9a8d5589ad0f', 8, 'formula', '{"expr": "Value at node = [C + (0.5 × V<sub>H</sub> + 0.5 × V<sub>L</sub>)] / (1 + i)", "label": "Compute first, then apply the exercise rule"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('715b9a8d5589ad0f', 9, 'prose', '{"text": "The value of the option itself is then recovered as the difference between the straight bond value and the callable value, which is generally easier than valuing the option directly."}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored');
insert into codex_blocks (unit_id, ord, block_type, payload, source_ref, reviewed_at, reviewed_by)
values
  ('d07bd06460d77cbc', 1, 'lead', '{"text": "For risky bonds, a spread must be added to the tree so the model reproduces the observed market price. Doing that in a way that strips out the option is what makes the spread comparable."}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('d07bd06460d77cbc', 2, 'key', '{"paras": ["The <strong>option-adjusted spread</strong> is the constant spread that, when added to all the one-period forward rates on the interest rate tree, makes the arbitrage-free value of the bond equal to its market price."]}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('d07bd06460d77cbc', 3, 'prose', '{"text": "Note the relationship to the Z-spread from LM1: <strong>the Z-spread for an option-free bond is simply its OAS at zero volatility</strong>. Once volatility is introduced, or an option is present, the two diverge."}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('d07bd06460d77cbc', 4, 'worked', '{"title": "Determining OAS by trial and error", "blocks": [{"text": "A three-year 4.25% annual coupon bond callable at par in one and two years, at 10% interest rate volatility. Market price 101.000.", "kind": "prose"}, {"text": "Trial 1 — add 30 bps to all forward rates", "kind": "step"}, {"expr": "Computed value = 100.973  →  below the market price of 101.000", "kind": "formula"}, {"text": "The value is too low, meaning the discount rates are too high. Because price and yield move inversely, try a <em>lower</em> spread.", "kind": "prose"}, {"text": "Trial 2 — add 28 bps", "kind": "step"}, {"expr": "Computed value = 101.010  →  slightly above the market price", "kind": "formula"}, {"text": "Converge", "kind": "step"}, {"text": "The spread is added <strong>to the rates in the tree</strong>, not subtracted from the coupon. That distinction is directly examinable.", "kind": "prose"}], "answer": "OAS = 28.55 bps"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('d07bd06460d77cbc', 5, 'heading_2', '{"text": "How volatility affects OAS"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('d07bd06460d77cbc', 6, 'key', '{"paras": ["For a <strong>callable</strong> bond, holding the market price constant, an <strong>increase</strong> in the volatility assumption <strong>lowers</strong> the OAS."]}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('d07bd06460d77cbc', 7, 'prose', '{"text": "The mechanism: higher volatility raises the value of the call, which lowers the model value of the callable bond. To bring the model value back up to the unchanged market price, a smaller spread must be added to the tree. The option has absorbed more of the yield premium, leaving less to be attributed to credit and liquidity."}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('d07bd06460d77cbc', 8, 'trap', '{"paras": ["This is why OAS matters for relative value. Two analysts using different volatility assumptions will compute different OAS for the <em>same</em> bond at the <em>same</em> price. An OAS comparison across bonds is only meaningful if the volatility assumption is consistent."]}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('d07bd06460d77cbc', 9, 'heading_2', '{"text": "Scenario analysis"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('d07bd06460d77cbc', 10, 'prose', '{"text": "Valuing bonds with embedded options over an investment horizon requires computationally intensive use of OAS technology, because the call or put decision must be evaluated against the evolution of interest rate scenarios during the holding period."}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('d07bd06460d77cbc', 11, 'prose', '{"text": "Performance over a horizon trades off reinvestment of cash flows against change in the bond''s value. For a 4.5% bond with five years to maturity over a one-year horizon: if the bond is option free, higher rates increase reinvestment income but reduce terminal principal value. Because the horizon is short, reinvestment income is relatively insignificant and performance is <strong>dominated by the change in principal value</strong> — so lower rates give superior performance."}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored');
insert into codex_blocks (unit_id, ord, block_type, payload, source_ref, reviewed_at, reviewed_by)
values
  ('9a6bbc904a851a6b', 1, 'lead', '{"text": "Yield duration measures assume cash flows do not change when yields change. That assumption is false for bonds with embedded options, which is why only one duration measure applies."}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('9a6bbc904a851a6b', 2, 'heading_2', '{"text": "Why modified duration fails"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('9a6bbc904a851a6b', 3, 'table_compare', '{"headers": ["", "Yield duration (e.g. modified)", "Curve duration (effective)"], "rows": [["Measures sensitivity to", "The bond''s own yield-to-maturity", "Benchmark interest rates — the government par curve"], ["Assumes", "Expected cash flows <strong>do not change</strong> when yield changes", "Cash flows may change with rates"], ["Valid for", "Option-free bonds only", "Straight bonds <em>and</em> bonds with embedded options"]]}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('9a6bbc904a851a6b', 4, 'prose', '{"text": "Because the values of embedded options are contingent on interest rates, the yield-duration assumption fails. For bonds with embedded options the only appropriate measure is <strong>effective duration</strong>, also called option-adjusted duration. Since it works for straight bonds too, practitioners tend to use it regardless of bond type."}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('9a6bbc904a851a6b', 5, 'formula', '{"expr": "Effective duration = (PV<sub>−</sub> − PV<sub>+</sub>) / (2 × ΔCurve × PV<sub>0</sub>)"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('9a6bbc904a851a6b', 6, 'prose', '{"text": "It indicates sensitivity to a <strong>100 bps parallel shift of the benchmark yield curve</strong>, specifically the government par curve."}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('9a6bbc904a851a6b', 7, 'heading_2', '{"text": "Comparing the three bonds"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('9a6bbc904a851a6b', 8, 'key', '{"paras": ["<strong>Neither a callable nor a putable bond can have effective duration exceeding that of the straight bond.</strong> Both options reduce duration relative to the option-free equivalent."]}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('9a6bbc904a851a6b', 9, 'table_compare', '{"headers": ["Condition", "Callable bond", "Putable bond"], "rows": [["Rates high relative to coupon", "Call out of the money; duration ≈ straight bond", "Put in the money; duration <strong>reduced</strong>"], ["Rates low relative to coupon", "Call in the money; duration <strong>reduced</strong>", "Put out of the money; duration ≈ straight bond"], ["Option deep in the money", "Duration resembles a straight bond maturing on the <strong>first exercise date</strong>", "Same — bond highly likely to be put on that date"]]}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('9a6bbc904a851a6b', 10, 'prose', '{"text": "The mechanism in each case is the same. The call gives the issuer the right to retire the bond at the call price, which limits price appreciation when rates decline. The put limits price depreciation when rates rise, because the investor can put the bond and reinvest at a higher yield. Either way the option truncates one side of the price response, and a truncated response is a smaller duration."}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored');
insert into codex_blocks (unit_id, ord, block_type, payload, source_ref, reviewed_at, reviewed_by)
values
  ('bc0b017928e98bd7', 1, 'lead', '{"text": "Effective duration averages the up-shift and down-shift responses. When an option is near the money that average conceals more than it reveals."}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('bc0b017928e98bd7', 2, 'heading_2', '{"text": "The asymmetry problem"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('bc0b017928e98bd7', 3, 'prose', '{"text": "Effective durations are normally calculated by averaging the price changes from shifting the benchmark curve up and down by the same amount. That works for option-free bonds. With embedded options it misleads, because price sensitivity is <strong>not symmetrical</strong> to positive and negative rate changes of equal magnitude."}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('bc0b017928e98bd7', 4, 'worked', '{"title": "Where the average breaks down", "blocks": [{"text": "A 4.5% bond maturing in five years, immediately callable at 100, on a 4% flat yield curve at 15% volatility.", "kind": "prose"}, {"headers": ["", "At 4% flat", "Rates up 30 bps", "Rates down 30 bps"], "rows": [["Value of the bond", "99.75", "99.17", "100.00"]], "aligns": ["", "num", "num", "num"], "kind": "table"}, {"text": "No matter how far rates decline, the price cannot exceed 100 — no investor pays more than the price at which the bond can be immediately called. The downside, by contrast, has no limit.", "kind": "prose"}, {"text": "Averaging a capped up-move against an uncapped down-move produces a number that describes neither scenario.", "kind": "prose"}], "answer": "Upside is capped at 100; downside is unbounded"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('bc0b017928e98bd7', 5, 'key', '{"paras": ["<strong>One-sided durations</strong> — effective duration computed separately for rates up and rates down — capture this better than the two-sided measure, particularly when the embedded option is <strong>near the money</strong>.<br><br>For a callable bond, one-sided <em>down</em>-duration is much smaller than one-sided <em>up</em>-duration. For a putable bond the asymmetry runs the other way."]}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('bc0b017928e98bd7', 6, 'heading_2', '{"text": "Key rate duration"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('bc0b017928e98bd7', 7, 'prose', '{"text": "Effective duration measures sensitivity to a <strong>parallel</strong> shift. Key rate duration measures sensitivity to a change at a <strong>specific maturity segment</strong>, holding other segments constant, which allows shaping risk to be identified and managed."}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('bc0b017928e98bd7', 8, 'prose', '{"text": "This matters more for bonds with embedded options than for straight bonds, because the exercise decision depends on rates around the exercise date rather than on the curve as a whole. A shift concentrated near the call date affects a callable bond very differently from an equivalent shift at the long end."}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('bc0b017928e98bd7', 9, 'heading_2', '{"text": "Effective convexity"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('bc0b017928e98bd7', 10, 'key', '{"paras": ["<strong>Callable bonds exhibit negative convexity when the call is near or in the money.</strong> The call truncates price appreciation, so the price–yield relationship bends the wrong way as rates fall.<br><br><strong>Putable bonds always exhibit positive convexity.</strong> The put truncates price <em>depreciation</em>, which reinforces rather than opposes the natural curvature."]}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('bc0b017928e98bd7', 11, 'table_compare', '{"headers": ["Bond type", "Convexity", "Why"], "rows": [["Straight", "Positive throughout", "Standard price–yield convexity"], ["Callable", "<strong>Negative</strong> when rates are low and the call is in the money", "Upside is capped at the call price"], ["Putable", "Positive throughout, and greater when the put is in the money", "Downside is floored at the put price"]]}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('bc0b017928e98bd7', 12, 'exam', '{"paras": ["A question describing a bond whose price appreciates less than it depreciates for equal yield moves is describing negative convexity, and therefore a callable bond with the call near or in the money. This is one of the most reliably tested points in the module."]}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored');
insert into codex_blocks (unit_id, ord, block_type, payload, source_ref, reviewed_at, reviewed_by)
values
  ('8fa5db751a950417', 1, 'heading_2', '{"text": "Formulas"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('8fa5db751a950417', 2, 'table_compare', '{"headers": ["Concept", "Formula"], "rows": [["Callable bond", "Straight bond − Call option"], ["Call option value", "Straight bond − Callable bond"], ["Putable bond", "Straight bond + Put option"], ["Put option value", "Putable bond − Straight bond"], ["Node value, callable", "min(computed value, call price)"], ["Node value, putable", "max(computed value, put price)"], ["Backward induction", "[C + (0.5V<sub>H</sub> + 0.5V<sub>L</sub>)] / (1 + i)"], ["Effective duration", "(PV<sub>−</sub> − PV<sub>+</sub>) / (2 × ΔCurve × PV<sub>0</sub>)"], ["Z-spread relationship", "Z-spread = OAS at zero volatility, for an option-free bond"]]}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('8fa5db751a950417', 3, 'heading_2', '{"text": "Directional relationships"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('8fa5db751a950417', 4, 'table_signal', '{"headers": ["If…", "Then…"], "rows": [["Interest rate volatility rises", "Both option values rise; callable falls, putable rises"], ["Volatility rises, price held constant", "OAS on a callable bond falls"], ["The yield curve flattens or inverts", "Call option value rises — more low forward rates on the tree"], ["Rates fall relative to the coupon", "Call moves into the money; callable duration falls"], ["Rates rise relative to the coupon", "Put moves into the money; putable duration falls"], ["The option is deep in the money", "Duration resembles a straight bond maturing at first exercise date"], ["A call is near or in the money", "Convexity turns negative"]]}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('8fa5db751a950417', 5, 'heading_2', '{"text": "Ten points for a final pass"}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('8fa5db751a950417', 6, 'list_ordered', '{"items": ["Callable subtracts the option, putable adds it — determined by which party holds the option.", "Option value rises with volatility for both types; the effect on the <em>bond</em> is opposite.", "The call caps upside as rates fall; the put floors downside as rates rise.", "Call option value rises as the curve flattens or inverts, because more tree nodes carry low forwards.", "At the node, callable takes the minimum and putable the maximum against the exercise price.", "OAS is the constant spread <em>added to the tree rates</em> that reproduces the market price.", "Z-spread equals OAS at zero volatility for an option-free bond.", "Higher assumed volatility lowers the OAS of a callable bond at a given price.", "Neither callable nor putable duration can exceed straight-bond duration.", "Callable bonds go negatively convex near the money; putable bonds stay positively convex throughout."]}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored'),
  ('8fa5db751a950417', 7, 'prose', '{"text": "Notes prepared from the CFA Program 2026 Level II curriculum, Volume 6, Learning Module 3. Worked examples follow the curriculum''s own illustrations; figures are as published."}'::jsonb, 'CFA 2026 L2 Fixed Income/LM3', now(), 'authored');
